    // ---------- Schneiden ----------
    "3D-Simulation": "3D simulation",
    "▶ Simulieren": "▶ Simulate",
    "„Simulieren\" fährt das gewählte Programm als Trockenlauf ab (vor dem Schnitt). Während der Ausführung folgt der Draht der gesendeten G-Code-Zeile. Ziehen = drehen · Rad = Zoom (am Cursor) · Würfel-Klick = Achsenansicht · Doppelklick = zurück.":
      "\"Simulate\" runs the selected program as a dry run (before cutting). During execution the wire follows the G-code line being sent. Drag = rotate · wheel = zoom (at cursor) · click cube = axis view · double-click = reset.",
    "Programm": "Program",
    "G-Code-Quelle wählen": "Choose G-code source",
    "G-Code (Kern/Negativschale)": "G-code (core/female mould)",
    "Guillotine": "Guillotine",
    "Abbrand-Kalibrierung": "Kerf calibration",
    "Quelle übernehmen": "Apply source",
    "kein Programm geladen": "no program loaded",
    "Start": "Start",
    "Pause": "Pause",
    "▶ Fortsetzen": "▶ Resume",
    "Stopp": "Stop",
    "⏹ Schnittabbruch": "⏹ Abort cut",
    "⌂ Fahren auf Nullpunkt": "⌂ Move to zero",
    "Schnitt sofort abgebrochen, Draht AUS. Zum Zurückfahren „Fahren auf Nullpunkt\" drücken.":
      "Cut aborted immediately, wire OFF. Press \"Move to zero\" to return.",
    "Fahre auf Nullpunkt … (erst X, dann Y)": "Moving to zero … (X first, then Y)",
    "Konsole": "Console",
    "Senden": "Send",
    "■ NOT-HALT — FEED HOLD": "■ EMERGENCY STOP — FEED HOLD",
    "⌂ Nach Not-Halt: Fahren auf Nullpunkt": "⌂ After emergency stop: move to zero",
    "Löst den Feed-Hold auf (Soft-Reset + $X), schaltet den Draht aus und fährt erst horizontal, dann vertikal auf den Nullpunkt.":
      "Releases the feed hold (soft reset + $X), switches the wire off and moves to zero — horizontal first, then vertical.",
    "Steuerung nach Stopp/Abbruch entsperrt (Soft-Reset + $X) — Handfahrt wieder möglich.":
      "Controller unlocked after stop/abort (soft reset + $X) — jogging is possible again.",
    "Handfahrt blockiert — Alarm lässt sich nicht quittieren: ": "Jogging blocked — alarm cannot be cleared: ",
    "Handfahrt abgelehnt: ": "Jog rejected: ",
    "Endschalter noch gedrückt (": "Limit switch still pressed (",
    "). Erst vom Schalter wegfahren.": "). Move away from the switch first.",
    "Die Steuerung steht in Hold. Die nächste Handfahrt löst den Zustand automatisch auf (Soft-Reset + $X).":
      "The controller is in hold. The next jog releases that state automatically (soft reset + $X).",
    "Schnitt sofort abgebrochen, Draht AUS. Zum Zurückfahren „Fahren auf Nullpunkt\" drücken; die Handfahrt entsperrt die Steuerung automatisch.":
      "Cut aborted immediately, wire OFF. Press \"Move to zero\" to return; jogging unlocks the controller automatically.",
    "Ersetzt keinen hardwareseitigen Not-Aus. Draht & Motoren müssen physisch abschaltbar bleiben.":
      "Does not replace a hardware emergency stop. Wire & motors must remain physically switchable off.",
    "Übernommenes Programm erscheint hier …": "Applied program appears here …",
    "Befehl eingeben (z. B. G0 X10) …": "Enter command (e.g. G0 X10) …",
    "Achsrichtungen invertieren · $3": "Invert axis directions · $3",
    "Kehrt die Drehrichtung der jeweiligen Achse um (Richtungsport-Invert-Maske $3). Änderungen werden sofort an die Steuerung gesendet und dort dauerhaft gespeichert. Erfordert eine Verbindung.":
      "Reverses the direction of the respective axis (direction port invert mask $3). Changes are sent to the controller immediately and stored there permanently. Requires a connection.",
    "Konnte $3 nicht setzen: ": "Could not set $3: ",
    "Richtungs-Invert-Maske gesetzt: $3=": "Direction invert mask set: $3=",

