    "Alle Punkte abhaken, dann starten. Liste anpassbar unter Einstellungen → Beschreibungen und Checkliste.": "Tick all items, then start. Edit the list under Settings → Descriptions & checklist.",
    "Ist die Checkliste eingeschaltet, erscheint sie beim Drücken von „Start“ im Reiter Schneiden. Erst wenn alle Punkte abgehakt sind, wird der Schnitt gestartet. Ein Punkt je Zeile; leere Zeilen werden ignoriert.": "When enabled, the checklist appears when pressing \"Start\" in the Cut tab. The cut only starts once every item is ticked. One item per line; empty lines are ignored.",
