    // ---------- Einstellungen: Dateien/Ordner ----------
    "Dieser Browser unterstützt keine feste Ordnerwahl (File System Access API). ":
      "This browser does not support fixed folder selection (File System Access API). ",
    "In Chrome oder Edge am Desktop werden hier Speicher- und Ladeordner wählbar; sonst gelten ":
      "In Chrome or Edge on desktop, save and load folders can be chosen here; otherwise ",
    "der Standard-Download-Ordner und der normale Datei-Dialog.":
      "the default download folder and the normal file dialog apply.",
    "Feste Ordner wählen. Beim Speichern öffnet ein Datei-Dialog (Name/Ordner wählbar), der im ":
      "Choose fixed folders. When saving, a file dialog opens (name/folder selectable) starting in the ",
    "Speicherordner startet. Beim Laden öffnet der Dialog im jeweiligen Ladeordner — je Dateityp getrennt.":
      "save folder. When loading, the dialog opens in the respective load folder — separately per file type.",
    "Ordner wählen…": "Choose folder…",
    "Beim Speichern und Laden öffnet immer der Windows-Explorer-Dialog (Name und Ordner frei wählbar). Er startet im Ordner des Dateityps, sonst im Standardordner für alle Dateien, sonst in „Dokumente\" (Empfehlung: Dokumente\\AI Foam Cut).":
      "Saving and loading always open the Windows Explorer dialog (name and folder freely selectable). It starts in the file type's folder, otherwise in the default folder for all files, otherwise in \"Documents\" (recommended: Documents\\AI Foam Cut).",
    "Standardordner": "Default folder",
    "Standardordner für alle Dateien (Speichern und Laden)": "Default folder for all files (save and load)",
    "Werkstoffdaten exportieren (.json)": "Export material data (.json)",
    "G-Code speichern (.gcode)": "Save G-code (.gcode)",
    "DXF exportieren (Profil, Tragfläche, CAD)": "Export DXF (airfoil, wing, CAD)",
    "3D-Segmente exportieren (.stl)": "Export 3D segments (.stl)",
    "Werkstoffdaten importieren (.json)": "Import material data (.json)",
    "SVG laden (.svg)": "Load SVG (.svg)",
    "3D-Modell laden (.stl/.obj)": "Load 3D model (.stl/.obj)",
    "Hintergrundbild laden (CAD, DXF-Formen)": "Load background image (CAD, DXF shapes)",
    "Noch kein Speicherordner festgelegt.": "No save folder set yet.",
    "Empfehlung: unter „Dokumente\" einen Ordner „AI Foam Cut\" anlegen — am einfachsten über „Einstellungen → Dateien → Ordnerbaum anlegen…\" (legt Unterordner je Dateityp an und verknüpft sie automatisch). Der Explorer-Dialog startet dann immer dort.":
      "Recommendation: create a folder \"AI Foam Cut\" under \"Documents\" — easiest via \"Settings → Files → Create folder tree…\" (creates subfolders per file type and links them automatically). The Explorer dialog will then always start there.",
    "Ordnerbaum anlegen": "Create folder tree",
    "Ordnerbaum anlegen…": "Create folder tree…",
    "Legt unterhalb eines gewählten Ordners (z. B. Dokumente\\AI Foam Cut) die Unterordner Projekte, Einstellungen, Werkstoffe, G-Code, Profile, DXF, STL, SVG und Bilder an und setzt alle Startordner unten automatisch darauf. Jede Zeile kann danach einzeln geändert werden. Vorhandene Unterordner werden wiederverwendet. Gibt es den Ordnerbaum schon (z. B. nach einer Neuinstallation), genügt „Vorhandenen Ordnerbaum wählen…“: damit wird nur neu verknüpft, ohne etwas anzulegen.":
      "Creates the subfolders Projekte, Einstellungen, Werkstoffe, G-Code, Profile, DXF, STL, SVG and Bilder below a chosen folder (e.g. Documents\\AI Foam Cut) and sets all start folders below to them automatically. Each row can be changed individually afterwards. Existing subfolders are reused If the folder tree already exists (e.g. after a reinstall), \"Use existing folder tree…\" is enough: it only re-links, without creating anything.",
    "Vorhandenen Ordnerbaum wählen…": "Use existing folder tree…",
    "Wurzelordner eines bereits vorhandenen Ordnerbaums wählen — es wird nichts neu angelegt.": "Choose the root folder of an existing folder tree — nothing is created.",
    "In diesem Ordner wurde kein Ordnerbaum gefunden. Bitte den Wurzelordner wählen (z. B. Dokumente\\AI Foam Cut) oder den Ordnerbaum neu anlegen.": "No folder tree was found in this folder. Please choose the root folder (e.g. Documents\\AI Foam Cut) or create the folder tree.",
    "Ordnerbaum verknüpft aus ": "Folder tree linked from ",
    "fehlen: ": "missing: ",
    "Keine Schreibfreigabe für den gewählten Ordner.": "No write permission for the selected folder.",
    "Ordnerbaum konnte nicht vollständig angelegt werden: ": "Folder tree could not be created completely: ",
    "Ordnerbaum angelegt in ": "Folder tree created in ",
    "Ordner": "Folder",
    "Einstellungen jetzt öffnen? (Abbrechen = diesmal Speicherort im Dialog wählen)": "Open settings now? (Cancel = choose the location in the dialog this time)",
    "Zurücksetzen": "Reset",
    "(gewählt)": "(selected)",
    "Übrige Dateien (G-Code, Block)": "Other files (G-code, block)",
    "Speichern — je Dateityp": "Save — per file type",
    "Laden — je Dateityp": "Load — per file type",
    "Projekt speichern (.json)": "Save project (.json)",
    "Einstellungen speichern (.json)": "Save settings (.json)",
    "Projekt laden (.json)": "Load project (.json)",
    "Einstellungen laden (.json)": "Load settings (.json)",
    "Profil laden (.dat)": "Load airfoil (.dat)",
    "DXF laden (.dxf)": "Load DXF (.dxf)",
    "Dieser Browser unterstützt keine Ordnerauswahl (File System Access API). Chrome/Edge am Desktop nutzen.":
      "This browser does not support folder selection (File System Access API). Use Chrome/Edge on desktop.",

    // ---------- Canvas-Beschriftungen ----------
