    "Sicherheitshöhe über dem Block: Reiter „Projektübersicht\".": "Safe height above the block: \"Project overview\" tab.",
    "Abstand, um den Profilober- und -unterseite an Nase und Endleiste vertikal getrennt werden (Ober +½ hoch, Unter −½ runter).":
      "Distance by which the airfoil upper and lower side are separated vertically at the nose and trailing edge (upper +½ up, lower −½ down).",
    "Als G-Code-Quelle „Abbrand-Kalibrierung\" im Reiter „Schneiden\" wählen und übernehmen.":
      "Select and apply \"Kerf calibration\" as the G-code source in the \"Cutting\" tab.",
    "Schnittspalt (Abbrand), Vorschub und Drahtheizung kommen aus dem Werkstoff-Betriebspunkt (Reiter „Projektübersicht\"). Der Vorschub hier ist der wirksame Wert und lässt sich für diesen Schnitt manuell überschreiben.":
      "Cut gap (kerf), feed and wire heating come from the material operating point (\"Project overview\" tab). The feed here is the effective value and can be manually overridden for this cut.",

