    "Dieselbe Tragfläche ist mehrfach als Ziel gewählt.": "The same wing is chosen as target more than once.",
    "Die Geometrie folgender Tragflächen wird ersetzt (Segmente, Profile und Holme gehen verloren): ":
      "The geometry of the following wings will be replaced (segments, airfoils and spars are lost): ",
