    "XFLR5 XML importieren…": "Import XFLR5 XML…",
    "XFLR5-Import ersetzt die komplette Tragfläche (alle Segmente, Profile und Holme). Fortfahren?":
      "XFLR5 import replaces the entire wing (all segments, airfoils and spars). Continue?",
    "XFLR5-/plane-XML: Planform (Sehnen, Spannweiten, Pfeilung aus xOffset, V-Form, Schränkung) wird übernommen. ACHTUNG: XFLR5-XML enthält KEINE Profilkoordinaten — es werden Platzhalterprofile gesetzt, die echten Profile unten als .dat zuordnen.":
      "XFLR5 / plane XML: planform (chords, spans, sweep from xOffset, dihedral, washout) is imported. NOTE: XFLR5 XML contains NO airfoil coordinates — placeholder airfoils are set; assign the real airfoils as .dat below.",
    "XFLR5-/plane-XML: Planform (Sehnen, Spannweiten, Pfeilung aus xOffset, V-Form, Schränkung) wird übernommen. ACHTUNG: XFLR5-XML enthält KEINE Profilkoordinaten — es werden Platzhalterprofile gesetzt, die echten Profile anschließend je Segment als .dat laden.":
      "XFLR5 / plane XML: planform (chords, spans, sweep from xOffset, dihedral, washout) is imported. NOTE: XFLR5 XML contains NO airfoil coordinates — placeholder airfoils are set; load the real airfoils per segment as .dat afterwards.",
    "XFLR5-Import: ": "XFLR5 import: ",
    "XFLR5-Import fehlgeschlagen: ": "XFLR5 import failed: ",
    "Kein <wing> in der Datei gefunden.": "No <wing> found in the file.",
    "XML nicht lesbar (Syntaxfehler).": "XML not readable (syntax error).",
    "DOMParser nicht verfügbar.": "DOMParser not available.",
    "Flügel braucht mindestens zwei Rippen.": "Wing needs at least two sections.",
    "Flügel enthält keine Segmente.": "Wing contains no segments.",
    "(Platzhalter – .dat laden)": "(placeholder – load .dat)",
    "Profile sind in XFLR5-XML NICHT enthalten. Bitte je Segment als .dat laden: ":
      "Airfoils are NOT contained in the XFLR5 XML. Please load each segment as .dat: ",
    "Planform Creator (.pc2) importieren…": "Import Planform Creator (.pc2)…",
    "Planform Creator 2 (.pc2): glatte/elliptische Fläche. Ein eigener Dialog zerlegt sie in wählbar viele/positionierte Trapeze (Live-Vorschau). Profile sind auch hier nur Namen — unten als .dat zuordnen. V-Form/Schränkung = 0 (reine Draufsicht).":
      "Planform Creator 2 (.pc2): smooth/elliptical planform. A dedicated dialog splits it into a chosen number/position of trapezoids (live preview). Airfoils are names only — assign as .dat below. Dihedral/washout = 0 (planform only).",
    "Der Import ersetzt die komplette Tragfläche (alle Segmente, Profile und Holme). Fortfahren?":
      "The import replaces the entire wing (all segments, airfoils and spars). Continue?",
