    "A = Abstände setzen, dann zwei Segmente/Linien an der Ecke anklicken (erster Abstand gilt fürs erste Objekt).": "D = set distances, then click two segments/lines at the corner (first distance applies to the first object).",
    "A = Alles, F = Fenster (zwei Punkte), O = auf Auswahl, V = vorherige Ansicht. Mausrad zoomt, mittlere Taste schiebt.": "A = all, W = window (two points), O = selection, P = previous view. Mouse wheel zooms, middle button pans.",
