    "BRUCH  Objekt am ersten Bruchpunkt anklicken:": "BREAK  Click object at first break point:",
    "Befehl abbrechen (Esc)": "Cancel command (Esc)",
    "Befehlszeile unten links: Kurzbefehl (l, pl, ci, rec, o, dr, sk …) ODER Koordinaten (x,y · @dx,dy · Länge<Winkel), Enter bestätigt. Buchstabe tippen füllt die Zeile automatisch. Liste aller Kürzel: „⌨ Befehle\" oben rechts.": "Command line bottom left: short command (l, pl, ci, rec, o, dr, sk …) OR coordinates (x,y · @dx,dy · length<angle), Enter confirms. Typing a letter fills the line automatically. List of all shortcuts: \"⌨ Commands\" top right.",
    "Beide Objekte müssen an der Ecke ein freies Ende haben (offene Linie/Polylinie).": "Both objects need a free end at the corner (open line/polyline).",
    "Bemaßung: Texthöhe (mm)": "Dimension: text height (mm)",
    "Bruch": "Break",
