    "Dreht alle Rippenkonturen gemeinsam um einen gemeinsamen Mittelpunkt — die Lage der Rippen zueinander bleibt erhalten (Rückgängig: Strg+Z).": "Rotates all rib contours together about a common centre — the ribs keep their position relative to each other (undo: Ctrl+Z).",
