    "Kreuzen-Fenster über die zu streckenden Ecken ziehen, dann Basis- und Zielpunkt. Nur die Punkte im Fenster wandern, der Rest bleibt.": "Drag a crossing window over the corners to stretch, then base and destination point. Only the points inside the window move.",
