    "Neuen Nullpunkt anklicken — alle Objekte werden so verschoben, dass dieser Punkt 0,0 wird (Export startet dort).": "Click the new origin — all objects are moved so that this point becomes 0,0 (export starts there).",
    "Nur offene Linien/Polylinien lassen sich dehnen.": "Only open lines/polylines can be extended.",
    "Objekt am ersten Bruchpunkt anklicken, dann zweiten Bruchpunkt klicken (Teilstück fällt weg). @ oder gleicher Punkt = nur teilen. E = ersten Punkt neu setzen.": "Click the object at the first break point, then click the second break point (the piece between is removed). @ or same point = split only. F = re-specify first point.",
    "Objekte": "Objects",
    "Objekte auf Ausrichtungspunkte skalieren?": "Scale objects to alignment points?",
    "Objekte sind parallel.": "Objects are parallel.",
    "Objekte wählen, Basispunkt, dann Faktor tippen. R = Referenz (Referenzlänge über zwei Punkte oder Zahl, dann neue Länge), K = Kopie behalten.": "Select objects, base point, then type the factor. R = reference (reference length by two points or number, then new length), C = keep a copy.",
    "Objekte wählen, Basispunkt, dann Winkel tippen oder Punkt klicken. R = Referenz (Winkel über zwei Punkte, dann neuer Winkel), K = Kopie behalten.": "Select objects, base point, then type the angle or click a point. R = reference (angle by two points, then new angle), C = keep a copy.",
    "Objekte wählen, dann 1. Quell-/Zielpunkt und 2. Quell-/Zielpunkt (verschiebt + dreht). Enter nach dem 1. Paar = nur verschieben. Zuletzt Abfrage, ob skaliert wird.": "Select objects, then 1st source/destination point and 2nd source/destination point (moves + rotates). Enter after the 1st pair = move only. Finally asks whether to scale.",
    "Objekte wählen, dann Rechteckig (Reihen, Spalten, Abstände) oder Polar (Mittelpunkt, Anzahl, Füllwinkel, mitdrehen).": "Select objects, then Rectangular (rows, columns, distances) or Polar (center, count, fill angle, rotate items).",
    "Objekte wählen, dann Ziellayer per Nummer/Klick wählen oder neuen Namen tippen.": "Select objects, then choose the target layer by number/click or type a new name.",
