    "Koordinaten-Modus der Befehlszeile: Abs = x,y vom Ursprung · Rel = x,y bzw. Länge<Winkel vom letzten Punkt. Präfix @ erzwingt relativ, # erzwingt absolut.": "Coordinate mode of the command line: Abs = x,y from the origin · Rel = x,y or length<angle from the last point. Prefix @ forces relative, # forces absolute.",
