    "Punkte je Spline-Segment": "Points per spline segment",
    "Einen Konturpunkt anfassen und ziehen. Bei Splines werden die Stützpunkte (Kontrollpunkte) verschoben — die Kurve rechnet sich neu.":
      "Grab and drag a contour point. For splines the control points are moved — the curve is recomputed.",
    "Zu wenige Stützpunkte zum Löschen.": "Too few control points to delete.",
    "Lädt ein Referenz-/Vorlagenbild (PNG/JPG/SVG) unter die Zeichnung — danach verschiebbar, skalierbar und drehbar. Nur Vorlage, nicht Teil der Geometrie/des Exports.":
      "Loads a reference/template image (PNG/JPG/SVG) under the drawing — then movable, scalable and rotatable. Template only, not part of the geometry/export.",
    "Auflösung der Spline-Kurve (mehr = glatter, aber größere DXF/mehr G-Code). Gilt für normale und tangentiale Splines.":
      "Spline curve resolution (more = smoother, but larger DXF/more G-code). Applies to normal and tangent splines.",
    "Punktzahl beim Zeichnen abfragen": "Ask for point count while drawing",
    "Bei jedem Kreis/jeder Ellipse nach der Punktzahl fragen (vorbelegt mit dem letzten Wert). Aus: es gilt fest die eingestellte Punktzahl.":
      "Ask for the point count for every circle/ellipse (prefilled with the last value). Off: the set point count is always used.",
