    // ============ DXF-Werkzeug-Hinweise & Sonstiges ============
    "Klick wählt eine Kontur (Umschalt = mehrere). Ziehen einer gewählten Kontur verschiebt sie.":
      "Click selects a contour (Shift = multiple). Dragging a selected contour moves it.",
    "Einen Konturpunkt anfassen und ziehen. Verändert die Form direkt.":
      "Grab a contour point and drag. Changes the shape directly.",
    "Auf einen Konturpunkt klicken, um ihn zu entfernen.": "Click a contour point to remove it.",
    "Startpunkt klicken, Endpunkt klicken. Fügt eine Linie auf dem aktiven Layer ein.":
      "Click start point, click end point. Inserts a line on the active layer.",
    "Zwei gegenüberliegende Ecken klicken. Fügt ein geschlossenes Rechteck ein.":
      "Click two opposite corners. Inserts a closed rectangle.",
    "Mittelpunkt klicken, dann Radius klicken. Fügt einen Kreis ein.":
      "Click the center, then the radius. Inserts a circle.",
    "Nacheinander Punkte klicken; Doppelklick oder „abschließen\". Nahe am Start = geschlossen.":
      "Click points one after another; double-click or \"finish\". Near the start = closed.",
    "Erst Konturen auswählen (Werkzeug „Auswählen\"), dann Basispunkt + Zielpunkt klicken.":
      "First select contours (\"Select\" tool), then click base point + target point.",
    "Wie Verschieben, legt aber eine Kopie ab (Auswahl bleibt erhalten).":
      "Like move, but leaves a copy (selection is kept).",
    "Auf den WEGZUSCHNEIDENDEN Teil einer Kontur klicken — er wird bis zur nächsten Kreuzung mit einer anderen Kontur entfernt.":
      "Click the part of a contour TO BE TRIMMED — it is removed up to the next intersection with another contour.",
    "Auf eine Kontur klicken, um sie zu löschen.": "Click a contour to delete it.",
    " — Exakt zeichnen: Koordinaten unten links eingeben (x,y absolut · @dx,dy relativ · Länge<Winkel polar), Enter setzt den Punkt.":
      " — Draw exactly: enter coordinates at the bottom left (x,y absolute · @dx,dy relative · length<angle polar), Enter sets the point.",

    // ============ Nachtrag 2026-09-05: 3D-Modell Platte — Anfahrwinkel, Reihen-Layout ============
    "fester Winkel vom Schwerpunkt (bei allen Segmenten gleiche Stelle)": "fixed angle from centroid (same spot on every segment)",
    "automatisch (Konturanfang)": "automatic (contour start)",
    "hinten (max. waagerecht)": "rear (max. horizontal)",
    "vorne (min. waagerecht)": "front (min. horizontal)",
    "oben (max. senkrecht)": "top (max. vertical)",
    "unten (min. senkrecht)": "bottom (min. vertical)",
    "Anfahrpunkt": "Entry point",
    "Anfahrwinkel (°)": "Entry angle (°)",
    "0° = hinten (+waagerecht), 90° = oben, 180° = vorne, 270° = unten; gegen den Uhrzeigersinn.": "0° = rear (+horizontal), 90° = top, 180° = front, 270° = bottom; counter-clockwise.",
    "Legt fest, an welchem Konturpunkt der Schnitt beginnt und endet (Ein-/Austrittsstelle des Drahts). „fester Winkel\": Der Eindringpunkt liegt dort, wo ein Strahl vom Profilschwerpunkt unter dem Anfahrwinkel die Kontur trifft — bei jedem Segment an derselben Stelle, sodass der Eindringschlitz beim Zusammensetzen der Segmente als Ausrichtmarke dient. In der Ansicht „◫ Segmentpaar\" auch per Klick auf die Schnittspur setzbar (übernimmt den Winkel). Für Tragflächenprofile ist „hinten\" (Endleiste) üblich.": "Defines the contour point where the cut starts and ends (wire entry/exit). \"fixed angle\": the entry point is where a ray from the profile centroid at the entry angle hits the contour — at the same spot on every segment, so the entry slit serves as an alignment mark when assembling the segments. Can also be set by clicking the cut path in the \"◫ Segment pair\" view (takes over the angle). For wing airfoils, \"rear\" (trailing edge) is usual.",
    "Automatisches Layout wiederherstellen": "Restore automatic layout",
    "Verwirft von Hand verschobene Positionen und legt die Stücke neu platzsparend in Reihen.": "Discards manually moved positions and re-packs the pieces into space-saving rows.",
    "Mehrere gleich DICKE Segmente (gleicher Ebenenabstand) in EINEM Schnitt aus einer Platte schneiden. Nur Segmente mit derselben Dicke wie das aktive Segment sind wählbar. Die Stücke werden platzsparend in Reihen gelegt (echte Stückbreiten, Reihen oben bündig, Segment 1 oben links), die Schnittreihenfolge läuft reihenweise von oben nach unten; die Verbindungswege führen nur durch den Freiraum zwischen den Teilen.": "Cut several segments of the SAME thickness (same plane spacing) from one plate in ONE program. Only segments with the same thickness as the active segment can be selected. Pieces are packed into rows (real piece widths, rows top-aligned, segment 1 top left); the cutting order runs row by row from top to bottom; connection paths run only through the free space between the pieces.",
    // ============ Nachtrag 2026-09-05: Reiter-Titel, Rippendesigner, Nasenschablonen, 3D-Modell, Maschine ($-Parameter), Block ablängen ============
    "3D-Modell": "3D model",
    "Rippendesigner": "Rib designer",
    "Holme": "Spars",
    "Werkstoffe werden hier mit allen Eigenschaften (ohne Dimension) angelegt und bearbeitet — links in der Seitenleiste. Die Dimension für das Projekt wird im Reiter „Projektübersicht“ eingegeben.":
      "Materials are created and edited here with all their properties (without dimensions) — in the sidebar on the left. The dimensions for the project are entered in the \"Project overview\" tab.",
    "Werkstoff auswählen und die Dimension (Höhe/Dicke) für das Projekt eingeben — links in der Seitenleiste. Die Werkstoff-Eigenschaften werden im Reiter „Werkstoff-Datenbank“ gepflegt.":
      "Select the material and enter the dimensions (height/thickness) for the project — in the sidebar on the left. Material properties are maintained in the \"Material database\" tab.",
    "Grundriss — Lage der Rippen & Holme": "Planform — position of ribs & spars",
    "Rippen — aus dem Tragflächendesign abgeleitet": "Ribs — derived from the wing design",
