    "Dreht beide Rippenkonturen des Segments in der Schnittebene um ihren Mittelpunkt (Rückgängig: Strg+Z). Ein Layer, den auch ein Nachbarsegment nutzt, dreht dort mit.": "Rotates both rib contours of the segment in the cutting plane about their centre (undo: Ctrl+Z). A layer shared with a neighbouring segment rotates there as well.",
