    "rot": "red",
    "Rumpf — NURBS-Fläche aus Seitenansicht, Draufsicht und Spanten": "Fuselage — NURBS surface from side view, top view and frames",
    "Rumpf — Loft-Fläche aus Bezier-Splines (Seitenansicht, Draufsicht, Spanten)": "Fuselage — lofted surface from Bezier splines (side view, top view, frames)",
    "Rumpf (Rumpf aus Bezier-Splines mit Tangenten: Dreitafel-Ansicht und Spanten)": "Fuselage (fuselage from Bezier splines with tangents: three-view drawing and frames)",
    "Seitenansicht bearbeiten: Ober-/Unterkante (Splines mit Tangenten) und Höhe der breitesten Stelle je Station": "Edit side view: top/bottom edge (splines with tangents) and height of the widest point per station",
