    // ---- Messwerkzeug 2D (measure2d.js: Kerndesign / Negativschale, 2026-09-18) ----
    "Messwerkzeug: Abstand, Kette, Winkel und Radius direkt in der Ansicht messen (Klick setzt Punkte, Fang auf Konturpunkte und -kanten)": "Measuring tool: distance, chain, angle and radius directly in the view (click places points, snaps to contour points and edges)",
