    "Zebra-Analyse:": "Zebra analysis:",
    "Streifen = Spiegelung eines Streifenmusters; Knicke oder Wellen in den Streifen zeigen Unstetigkeiten der Fläche, glatte Streifen = glatte Fläche": "stripes = reflection of a striped pattern; kinks or waves in the stripes reveal surface discontinuities, smooth stripes = smooth surface",
    "nur mit WebGL-Darstellung (Darstellung „fein“ oder „schnell“, kein Drahtgitter)": "WebGL rendering only (rendering \"fine\" or \"fast\", no wireframe)",
    "Nur mit WebGL-Darstellung („fein“ oder „schnell“, kein Drahtgitter).": "WebGL rendering only (\"fine\" or \"fast\", no wireframe).",
    "Streifen": "Stripes",
    "Anzahl der Streifen über den Spiegelwinkel: mehr Streifen = feinere Prüfung": "Number of stripes across the reflection angle: more stripes = finer check",
    "Richtung": "Direction",
    "senkrecht": "vertical",
    "waagrecht": "horizontal",
    "Deckkraft": "Opacity",
