    "Bezug": "Reference",
    "Bauteil": "Part",
    "Ansicht": "View",
    "Winkel": "Angle",
    "Bauteil: feste Streifenachse im Modell – die Streifen laufen über Randbogen und Winglet durch und drehen sich mit dem Bauteil. Ansicht: Achse in der Bildebene (klassisches CAD-Zebra, Muster ändert sich beim Drehen).": "Part: fixed stripe axis in the model – the stripes run continuously across tip and winglet and rotate with the part. View: axis in the screen plane (classic CAD zebra, pattern changes when rotating).",
    "Winkel der Streifenachse in der Bildebene: 0° = senkrecht, 90° = waagrecht": "Angle of the stripe axis in the screen plane: 0° = vertical, 90° = horizontal",
    "Winkel der Streifenachse zum Bauteil: 0° = Sehnenrichtung, 90° = Spannweite (Streifen quer zur Spannweite, zeigen die Profilkrümmung)": "Angle of the stripe axis relative to the part: 0° = chord direction, 90° = span (stripes across the span, showing the airfoil curvature)",
    "WebGL nicht verfügbar – Darstellung über Canvas 2D": "WebGL not available – rendering via Canvas 2D",
    "Darstellung": "Rendering",
    "fein (glatt, volle Auflösung)": "fine (smooth, full resolution)",
    "schnell (flach, geringere Auflösung)": "fast (flat, lower resolution)",
    "kompatibel (ohne WebGL)": "compatible (no WebGL)",
    "Fein: glatt schattiert mit Glanzlicht in Geräteauflösung. Schnell: flache Schattierung in Bildschirmauflösung, beim Drehen halbiert – für schwache Grafik. Kompatibel: alter Zeichenpfad ohne WebGL (langsam, Sortierfehler möglich; wird automatisch benutzt, wenn WebGL fehlt).": "Fine: smooth shading with specular highlight at device resolution. Fast: flat shading at screen resolution, halved while rotating – for weak graphics. Compatible: old drawing path without WebGL (slow, sorting artefacts possible; used automatically when WebGL is missing).",
    "Schnittansicht: 2D-Schnitt durch das Modell ein-/ausblenden (Ebene und Lage im Fenster links unten)": "Section view: toggle the 2D section through the model (plane and position in the panel at bottom left)",
