    // --- Reiter „Fräse" (fraese.js) ---
    "Fräse": "Mill",
    "Fräse: Geometrie & Jobs": "Mill: geometry & jobs",
    "Fräse: Werkzeug & Schnittwerte": "Mill: tool & cutting values",
