    "Fräse: Haltestege (Tabs)": "Mill: holding tabs",
    "Fräse: G-Code": "Mill: G-code",
    "Fräse: Maschine": "Mill: machine",
    "Konturen aus einer DXF-Datei oder aus dem CAD-Reiter übernehmen. Jede Kontur wird ein Job mit eigener Operation (außen / innen / auf der Linie / Tasche / Bohren). Reihenfolge = Bearbeitungsreihenfolge (Außenkontur zuletzt, damit das Teil bis zum Schluss gehalten wird).": "Take contours from a DXF file or from the CAD tab. Each contour becomes a job with its own operation (outside / inside / on the line / pocket / drill). List order = machining order (outside contour last so the part stays held until the end).",
    "CAD: Auswahl": "CAD: selection",
