    "wie gezeichnet (0/0 der Zeichnung)": "as drawn (0/0 of the drawing)",
    "Wo der Werkstück-Nullpunkt (X0/Y0) relativ zur Geometrie liegt. Z0 ist immer die Werkstückoberkante.": "Where the work zero (X0/Y0) lies relative to the geometry. Z0 is always the top of the workpiece.",
