    "Durchmesser des Fräsers. Bestimmt den seitlichen Versatz bei Außen-/Innenkonturen und die Bahnbreite in Taschen.": "Diameter of the cutter. Sets the lateral offset for outside/inside contours and the path width in pockets.",
    "Spindeldrehzahl (1/min)": "Spindle speed (rpm)",
    "S-Wert für M3. 0 = keine Spindelbefehle im Programm (z. B. Spindel von Hand geschaltet).": "S value for M3. 0 = no spindle commands in the program (e.g. spindle switched by hand).",
    "Vorschub XY (mm/min)": "Feed XY (mm/min)",
    "Eintauch-Vorschub Z (mm/min)": "Plunge feed Z (mm/min)",
    "Vorschub beim senkrechten Eintauchen und Bohren — deutlich niedriger als der XY-Vorschub.": "Feed for vertical plunging and drilling — much lower than the XY feed.",
    "Gesamttiefe (mm)": "Total depth (mm)",
    "Frästiefe ab Werkstückoberkante (positiv eingeben). Für Durchbrüche etwas mehr als die Materialdicke (Opferplatte!).": "Milling depth from the top of the workpiece (enter positive). For through-cuts slightly more than the material thickness (spoil board!).",
    "Zustellung je Durchgang (mm)": "Depth per pass (mm)",
    "Tiefe je Durchgang. Richtwert: halber Fräserdurchmesser bei Holz/Schaum, weniger bei Kunststoff/Alu.": "Depth per pass. Rule of thumb: half the cutter diameter for wood/foam, less for plastic/aluminium.",
    "Sicherheitshöhe Z (mm)": "Safe height Z (mm)",
    "Höhe über Z0 für Eilgänge zwischen den Konturen (über Spannmittel!).": "Height above Z0 for rapids between contours (above the clamps!).",
    "Fräsrichtung": "Milling direction",
    "Gleichlauf (empfohlen)": "Climb (recommended)",
    "Gegenlauf": "Conventional",
    "Gleichlauf: Fräser läuft mit der Vorschubrichtung (rechtsdrehende Spindel: Außenkontur im Uhrzeigersinn) — sauberere Kante, weniger Ausriss. Gegenlauf bei sehr weichem Aufbau oder Spiel in der Mechanik.": "Climb: the cutter runs with the feed direction (clockwise spindle: outside contour clockwise) — cleaner edge, less tear-out. Conventional for a very flexible setup or backlash in the mechanics.",
    "Tasche: seitliche Zustellung (%)": "Pocket: stepover (%)",
    "Abstand der Bahnen in Taschen in Prozent des Fräserdurchmessers (≤ 50 % = keine Reststege).": "Spacing of the paths in pockets as a percentage of the cutter diameter (≤ 50 % = no remaining ridges).",
    "Bohren: Spanbruch alle (mm)": "Drilling: chip break every (mm)",
    "0 = in einem Zug bohren; sonst nach jeweils dieser Tiefe kurz zurückziehen (Späne brechen).": "0 = drill in one go; otherwise retract briefly after each of this depth (break chips).",
    "Haltestege (Tabs)": "Holding tabs",
    "Stege, die das Teil beim letzten Durchgang an Außen-/Innenkonturen halten. Werden gleichmäßig über die Kontur verteilt und in der Vorschau grün markiert. 0 = keine Stege.": "Tabs that hold the part during the last pass on outside/inside contours. Spread evenly over the contour and marked green in the preview. 0 = no tabs.",
