    "Grenzen des Arbeitsraums ab Werkstück-Nullpunkt. Überschreitet ein Programm diese Werte, wird der Start verweigert. 0 = kein Limit. Gehört zu den Einstellungen (nicht zum Projekt).": "Limits of the working area from the work zero. If a program exceeds these values, the start is refused. 0 = no limit. Part of the settings (not the project).",
