    "Lückenbreite ist nicht größer als der Abbrand — der Draht passt nicht durch die Lücke.": "The gap is not wider than the kerf — the wire does not fit through the gap.",
    "Teile liegen enger als der Abbrand — ihre Schnittbahnen verschmelzen. Abstand vergrößern.": "Parts are closer than the kerf — their cut paths merge. Increase the spacing.",
