    "Die aktuellen Einstellungen (Stärke, Breite, Enden, Ecken, Serifen, Abstände …) unter einem Namen als eigene Schriftart speichern": "Save the current settings (weight, width, ends, corners, serifs, spacing …) under a name as your own font",
