    "Aus der Liste entfernen: ": "Remove from the list: ",
    "Linienschrift: jede Schriftart besteht aus Mittellinien — Höhe, Strichstärke, Breite, Enden, Ecken, Rundungen und Serifen sind frei einstellbar. Eigene Einstellungen lassen sich als Schriftart speichern.": "Stroke font: every font consists of centre lines — height, stroke weight, width, ends, corners, roundness and serifs can be set freely. Your own settings can be saved as a font.",
    "Schriftdatei: Umrisse der Schrift. Die Stärke lässt sich über „Stärke-Korrektur\" fetter oder dünner machen. Die verwendeten Zeichen werden im Projekt mitgespeichert.": "Font file: outlines of the font. Use “Weight correction” to make it bolder or thinner. The characters used are stored in the project.",
