    "Kontur (gleicher Mindestabstand)": "contour (equal minimum gap)",
    "Kontur: jeder Buchstabe rückt so nah an den vorigen, bis der kleinste waagerechte Abstand dem Wert „Konturabstand\" entspricht — gleichmäßige Lücken, wichtig für den Schnitt (Abbrand).": "Contour: each letter moves up to the previous one until the smallest horizontal gap equals the “Contour gap” — even gaps, important for cutting (kerf).",
