    "Der Draht kann nicht springen: Einschnitt = feiner Schlitz (Abbrandbreite) an der dünnsten Stelle hinein und wieder heraus; Lücke = offener Spalt, Innenform wird Teil der Außenkontur; füllen = Innenform bleibt Schaum.": "The wire cannot jump: slit = fine slot (kerf width) in and back out at the thinnest point; gap = open gap, the counter becomes part of the outer contour; fill = the counter stays foam.",
