    "Abstand X vom Nullpunkt (mm)": "Distance X from origin (mm)",
    "Abstand Block ↔ linkes Portal (mm)": "Distance block ↔ left gantry (mm)",
    "Quelle „Schriften\": Hier gelten Vorschub, Geschwindigkeit außerhalb Block und die Profil-Schnittrichtung (Oberseite/Unterseite zuerst). Schnittrichtung, Tragflächenseite und Blockschnitt betreffen nur Tragflächen.": "Source “Lettering”: feed, speed outside the block and the profile cut direction (top/bottom first) apply here. Cut direction, wing side and block cut only concern wings.",
    "Schriften: Lücke zwischen Nullpunkt (X=0) und linker Blockkante; +X zeigt nach rechts in den Block.": "Lettering: gap between the origin (X=0) and the left block edge; +X points right into the block.",
    "Je Teil: seitlich einfahren, Oberseite zuerst, dann Unterseite": "Per part: enter from the side, top first, then bottom",
    "Je Teil: seitlich einfahren, Unterseite zuerst, dann Oberseite": "Per part: enter from the side, bottom first, then top",
    "Blocklage (Abstand X/Y vom Nullpunkt, Lage zwischen den Portalen), Vorschub und Schnittfolge (Oberseite/Unterseite zuerst) stellt der Reiter „G-Code\" ein.": "Block position (distance X/Y from origin, position between the gantries), feed and cut order (top/bottom first) are set in the “G-code” tab.",
    // ---- Schriften: Werkstoff in der Projektübersicht (2026-09-18) ----
    "Werkstoff DXF-Formen / 3D-Modell / Schriften": "Material DXF shapes / 3D model / lettering",
    "Werkstoff Schriften": "Material lettering",
    "Werkstoff für die Quellen „DXF-Formen\", „3D-Modell/Platte\" und „Schriften\" (Abbrand, Heizung, Vorschub automatisch). Eine Dicke ist hier nicht nötig — die Blockmaße kommen aus der Form, dem Modell bzw. der Schrift (Blockdicke im Reiter „Schriften\").": "Material for the sources “DXF shapes”, “3D model/plate” and “Lettering” (kerf, heating, feed automatic). No thickness is needed here — the block dimensions come from the shape, the model or the text (block thickness in the “Lettering” tab).",
    "Werkstoff der Schriften (Abbrand, Heizung, Vorschub automatisch) — dieselbe Zuordnung wie in der Projektübersicht.": "Material of the lettering (kerf, heating, feed automatic) — the same assignment as in the project overview.",
    // ---- Abbrandlinien in wahrer Dicke (2026-09-18) ----
    "Abbrand in wahrer Dicke": "Kerf at true width",
    "Abbrandlinien (Schnittspur)": "Kerf lines (cut trace)",
    "Deckkraft des Bands": "Band opacity",
    "Band = wahre Abbrandbreite (Schnittspalt) im Maßstab": "Band = true kerf width (cut gap) to scale",
    "Legt unter die Abbrandlinie (Drahtmitte) ein halbtransparentes Band in der echten Breite des Schnittspalts — es reicht von der Sollkontur bis in den Abfall. Gilt nur für diese Ansicht; Deckkraft unter Einstellungen → Farben.": "Draws a semi-transparent band with the real width of the cut gap under the kerf line (wire centre) — it reaches from the nominal contour into the waste. Applies to this view only; opacity under Settings → Colors.",
    "In wahrer Dicke: unter die Abbrandlinie (Drahtmitte) kommt ein halbtransparentes Band in der echten Breite des Schnittspalts im aktuellen Zoom — von der Sollkontur bis in den Abfall. Je Designebene einzeln (Kerndesign inkl. Schalen- und Holmschnitt, Negativdesign, DXF-Formen, 3D-Modell, Schriften).": "At true width: the kerf line (wire centre) gets a semi-transparent band with the real width of the cut gap at the current zoom — from the nominal contour into the waste. Set separately per design level (core design incl. shell and spar cuts, negative design, DXF shapes, 3D model, lettering).",
    "Häkchen = Band an, Regler = Deckkraft des Bands.": "Checkbox = band on, slider = band opacity.",
    "Band in der echten Breite des Schnittspalts unter der Abbrandlinie (nur diese Ansicht; Deckkraft unter Einstellungen → Farben)": "Band with the real width of the cut gap under the kerf line (this view only; opacity under Settings → Colors)",
    " mm/min). Abbrand-Berechnung Kerndesign: ": " mm/min). Kerf calculation core design: ",
    "Gilt nur für das Kerndesign — Negativdesign, DXF-Formen und 3D-Modell haben eine eigene Einstellung.": "Applies to the core design only — negative design, DXF shapes and 3D model have their own setting.",
    "Gilt nur für DXF-Formen — Kerndesign, Negativdesign und 3D-Modell haben eine eigene Einstellung.": "Applies to DXF shapes only — core design, negative design and 3D model have their own setting.",
    "Gilt nur für das 3D-Modell (Segment und Platte) — Kerndesign, Negativdesign und DXF-Formen haben eine eigene Einstellung.": "Applies to the 3D model only (segment and plate) — core design, negative design and DXF shapes have their own setting.",
    "Band in der echten Breite des Schnittspalts unter der Schnittbahn": "Band with the real width of the cut gap under the cut path",
