    "Nichts rückgängig zu machen.": "Nothing to undo.",
    "Radius zu groß für diese Ecke.": "Radius too large for this corner.",
    "Fasenabstand zu groß für diese Ecke.": "Chamfer distance too large for this corner.",
    "Radius zu groß.": "Radius too large.",
    "Fasenabstand zu groß.": "Chamfer distance too large.",
