    "Werkstoffe werden hier mit allen Eigenschaften (ohne Dimension) angelegt und bearbeitet — links in der Seitenleiste. Werkstoff und Dicke werden im Reiter „Projektübersicht“ je Tragfläche zugewiesen.": "Materials are created and edited here with all their properties (without dimensions) — in the sidebar on the left. Material and thickness are assigned per wing in the “Project overview” tab.",
