    // --- Reiter Aerodynamik (aero.js) ---
    "Aerodynamik": "Aerodynamics",
    "Flugzeug-Editor": "Aircraft editor",
    "Referenz & Schwerpunkt": "Reference & center of gravity",
    "Analyse": "Analysis",
    "Profilanalyse": "Airfoil analysis",
    "Anstellwinkel nachbilden": "Show angle of attack",
    "Das Flugzeug wird um den Anstellwinkel des gezeigten Zustands (Trimm bzw. Kurvenflug) genickt, die Anströmung bleibt waagerecht.": "The aircraft is pitched by the angle of attack of the displayed state (trim or turning flight); the airflow stays horizontal.",
    "Flugzeug um den Anstellwinkel des gezeigten Zustands nicken (Anströmung waagerecht)": "Pitch the aircraft by the angle of attack of the displayed state (airflow horizontal)",
    "Profilpolaren (eigene Analyse)": "Airfoil polars (standalone analysis)",
    "Rechnet die Profile der Tragflächen für sich (2D, ohne Flugzeug) über eine Re-Schar: Auftrieb, Widerstand, Gleitzahl, Moment, Umschlag — wie die Profilanalyse in XFLR5.": "Computes the wings' airfoils on their own (2D, no aircraft) over a set of Re numbers: lift, drag, L/D, moment, transition — like the airfoil analysis in XFLR5.",
    "Re-Zahlen": "Re numbers",
    "Liste, durch Komma oder Leerzeichen getrennt; k = Tausend, M = Million (z. B. 50k 100k 200k 400k)": "List separated by comma or space; k = thousand, M = million (e.g. 50k 100k 200k 400k)",
    "Polarentyp": "Polar type",
    "Typ 1 — feste Re-Zahl": "Type 1 — fixed Re number",
    "Typ 2 — Re·√cl = konstant (feste Masse)": "Type 2 — Re·√cl = constant (fixed mass)",
    "Typ 1: jede Kurve bei fester Re-Zahl (fester Fahrt). Typ 2: die Fahrt folgt dem Auftrieb wie im Flug mit fester Masse — die Re-Zahl ist die bei cl = 1, bei kleinem cl wird sie größer.": "Type 1: each curve at a fixed Re number (fixed speed). Type 2: speed follows lift as in flight at fixed mass — the Re number given is the one at cl = 1, it grows at small cl.",
