    "Profil-Rechnung je Streifen (2D): Polaren cd(cl, Re) und cl max(Re) fließen in die 3D-Analyse ein. Einstellungen wirken bei der nächsten Analyse.": "Per-strip airfoil calculation (2D): polars cd(cl, Re) and cl max(Re) feed the 3D analysis. Settings take effect on the next analysis.",
    "Jedes Bauteil ist eine Tragfläche aus dem Projekt (auch Höhen-/Seitenleitwerk als eigene Tragfläche anlegen). Lage in mm: X nach hinten, Y zur Seite, Z nach oben — bezogen auf die Wurzel-Nasenleiste.": "Each component is a wing from the project (create stabilizer/fin as their own wings). Position in mm: X aft, Y sideways, Z up — relative to the root leading edge.",
