    "Liefert Fläche, Spannweite und Bezugstiefe für alle Beiwerte.": "Provides area, span and reference chord for all coefficients.",
    "Schwerpunkt X (mm)": "Center of gravity X (mm)",
    "Hinter der Wurzel-Nasenleiste des Bezugssystems (X = 0). Bestimmt Nickmoment, Trimm und Stabilitätsmaß.": "Aft of the root leading edge of the reference frame (X = 0). Determines pitching moment, trim and static margin.",
    "Schwerpunkt Z (mm)": "Center of gravity Z (mm)",
    "Abflugmasse (g)": "Takeoff mass (g)",
    "0 = keine Geschwindigkeits-/Sinkspalten. Mit Masse rechnet die Tabelle je CL die Fluggeschwindigkeit.": "0 = no speed/sink columns. With a mass the table computes the flight speed for each CL.",
    "Masse aus Gewichtsschätzung übernehmen": "Take mass from weight estimate",
    "Summe der Gewichtsschätzung (Projektübersicht) über alle Bauteile.": "Sum of the weight estimate (project overview) over all components.",
    "Keine Gewichtsschätzung vorhanden (Reiter Projektübersicht).": "No weight estimate available (project overview tab).",
    "Luftdichte (kg/m³)": "Air density (kg/m³)",
    "Wirbelleiter-Verfahren (VLM, eingebauter Löser, gegen AVL validiert): rechnet reibungsfrei — induzierter Widerstand, Momente und Neutralpunkt sind gut, der Profilwiderstand kommt pauschal aus CD0.": "Vortex lattice method (VLM, built-in solver, validated against AVL): inviscid — induced drag, moments and neutral point are good, profile drag is a flat CD0 estimate.",
    "Getrimmten Flug rechnen (Cm = 0)": "Compute trimmed flight (Cm = 0)",
    "Der Anstellwinkel wird so bestimmt, dass das Nickmoment um den Schwerpunkt verschwindet — der stationäre Gleitflug.": "The angle of attack is set so the pitching moment about the CG vanishes — steady gliding flight.",
