    "der Halbspannweite": "of the half span",
    "Randabriss-Gefahr! Mehr negative Schränkung außen oder gutmütigeres Außenprofil hilft.": "Tip-stall risk! More washout at the tip or a more forgiving tip airfoil helps.",
