    // ============ Reiter „Rippenfläche“ (rippenflaeche.js, 2026-09-20) ============
    "Rippenfläche": "Rib-built wing",
    "Grundriss — Rippenlagen, Holme, Ruder & Geodäten": "Plan view — rib positions, spars, control surfaces & geodetics",
    "Bauteile — geschachtelt wie im DXF": "Parts — nested as in the DXF",
    "Erst im Reiter „Tragflächendesigner\" eine Tragfläche anlegen.": "First create a wing in the \"Wing designer\" tab.",
    "Aus Rippenfläche (Bausatz)": "From rib-built wing (kit)",
    "Wie die Rippen über die Spannweite verteilt werden. „Positionen von Hand\" übernimmt die aktuelle Verteilung als Startwerte.": "How the ribs are distributed over the span. \"Positions by hand\" takes the current distribution as starting values.",
    "Erzwingt zusätzlich eine Rippe an der Wurzel, an jedem Segmentstoß und am Rand.": "Additionally forces a rib at the root, at every segment joint and at the tip.",
    "Ergibt derzeit ": "Currently gives ",
    " Rippen über ": " ribs over ",
    "Werkstoffe (Holz & Platten)": "Materials (wood & sheet)",
    "Eigene Werkstoffliste NUR für die Rippenfläche: Holzarten und Platten mit ihren handelsüblichen Lieferstärken und der Rohdichte. Sie gehört zum Projekt und ist frei änderbar — die Startwerte sind übliche Modellbau-Werkstoffe. Die Rohdichte liefert die Massen in der Stückliste.": "Separate material list ONLY for the rib-built wing: woods and sheet materials with their standard stock thicknesses and density. It belongs to the project and is freely editable — the initial values are common model-building materials. The density provides the masses in the parts list.",
    "Werkstoff entfernen": "Remove material",
    "Lieferstärken (mm)": "Stock thicknesses (mm)",
    "Mit Komma getrennt, z. B. 1, 1.5, 2, 3": "Comma-separated, e.g. 1, 1.5, 2, 3",
    "+ Werkstoff anlegen": "+ Add material",
    "↻ Standardliste wiederherstellen": "↻ Restore default list",
    "Die Werkstoffliste dieses Moduls auf die Startwerte zurücksetzen? Eigene Einträge gehen verloren.": "Reset this module's material list to the default values? Your own entries will be lost.",
    "Rippengruppen (Werkstoff & Stärke)": "Rib groups (material & thickness)",
    "Rippen lassen sich zu Gruppen zusammenfassen — jede Gruppe hat einen eigenen Werkstoff und eine eigene Materialstärke. Die Stärke bestimmt die Breite der Schlitze in Rippenkamm und Helling und die Aufteilung auf die Platten.": "Ribs can be combined into groups — each group has its own material and its own material thickness. The thickness determines the width of the slots in the rib comb and the jig, and how the parts are split across sheets.",
    "— offen —": "— open —",
    "Werkstoff aus der Holz-Datenbank dieses Moduls (Menü „Werkstoffe (Holz & Platten)\"). Darunter stehen zusätzlich die Werkstoffe des Projekts. Bestimmt Lieferstärken, Plattenaufteilung und Masse in der Stückliste.": "Material from this module's wood database (menu \"Materials (wood & sheet)\"). Below it the project materials are listed as well. Determines stock thicknesses, sheet layout and mass in the parts list.",
    "Handelsübliche Lieferstärken des gewählten Werkstoffs.": "Standard stock thicknesses of the selected material.",
    " — frei": " — free",
    "Balsa leicht": "Balsa light",
    "Balsa mittel": "Balsa medium",
    "Balsa hart": "Balsa hard",
